package com.live_jgv.worker.academic;
import com.live_jgv.worker.domain.TransportMessage;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
import org.springframework.dao.DataAccessResourceFailureException;
import java.time.*;import java.nio.charset.StandardCharsets;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AcademicFlowTest {
 JdbcTemplate jdbc;PlatformTransactionManager manager;JdbcAcademicCommandStore store;
 AcademicCommand command(AcademicCommand.CommandType type){return new AcademicCommand(1,"cmd","match","goal",type,Instant.EPOCH);}
 TransportMessage input(AcademicCommand c){return new TransportMessage("academic-test/1",c.commandId(),"","betting_commands",c.json().getBytes(StandardCharsets.UTF_8),"{}");}
 @BeforeEach void setup(){jdbc=mock(JdbcTemplate.class);manager=mock(PlatformTransactionManager.class);when(manager.getTransaction(any())).thenReturn(new SimpleTransactionStatus());when(jdbc.update(anyString(),any(Object[].class))).thenReturn(1);store=new JdbcAcademicCommandStore(jdbc,new TransactionTemplate(manager));}
 @Test void W01SuspendIsPersistedBeforeReturn(){var c=command(AcademicCommand.CommandType.SUSPEND_BETS);assertEquals(AcademicCommandStore.Outcome.RECORDED,new AcademicCommandHandler(store,new AcademicCommandCodec()).receive(input(c)));verify(jdbc).update(contains("INSERT INTO betting_worker.academic_command"),eq("cmd"),eq("match"),eq("goal"),eq("SUSPEND_BETS"),anyString(),eq(c.json()),eq("SIMULATED_SUSPENDED"));var order=inOrder(jdbc,manager);order.verify(jdbc).update(contains("academic_delivery"),any(Object[].class));order.verify(manager).commit(any());}
 @Test void W02ResumeRecordsOnlyAcademicAction(){var c=command(AcademicCommand.CommandType.RESUME_BETS);store.record(c,input(c));verify(jdbc).update(contains("academic_command("),eq("cmd"),eq("match"),eq("goal"),eq("RESUME_BETS"),anyString(),eq(c.json()),eq("SIMULATED_RESUMED"));
  for(var invocation:mockingDetails(jdbc).getInvocations()){String sql=invocation.getArgument(0);assertTrue(sql.contains("betting_worker.academic_"));assertFalse(sql.contains("authorization_grant"));assertFalse(sql.contains("operation("));}}
 @Test void W03DatabaseFailurePropagatesWithoutAck(){when(jdbc.update(contains("academic_delivery"),any(Object[].class))).thenThrow(new DataAccessResourceFailureException("offline failure"));var c=command(AcademicCommand.CommandType.SUSPEND_BETS);assertThrows(DataAccessResourceFailureException.class,()->new AcademicCommandHandler(store,new AcademicCommandCodec()).receive(input(c)));verify(manager).rollback(any());verify(manager,never()).commit(any());}
 void duplicate(AcademicCommand c,String canonical){when(jdbc.update(contains("academic_command("),any(Object[].class))).thenReturn(0);when(jdbc.queryForList(contains("FOR UPDATE"),any(Object[].class))).thenReturn(List.of(Map.of("command_id",c.commandId(),"canonical_payload",canonical)));}
 @Test void D01IdenticalDuplicateOnlyIncrementsDeliveryCount(){var c=command(AcademicCommand.CommandType.SUSPEND_BETS);duplicate(c,c.json());assertEquals(AcademicCommandStore.Outcome.DUPLICATE,store.record(c,input(c)));verify(jdbc).update(contains("delivery_attempts=delivery_attempts+1"),eq("cmd"));}
 @Test void D02ConflictingDuplicateCannotReplaceResult(){var c=command(AcademicCommand.CommandType.RESUME_BETS);duplicate(c,command(AcademicCommand.CommandType.SUSPEND_BETS).json());assertEquals(AcademicCommandStore.Outcome.IDENTITY_CONFLICT,store.record(c,input(c)));verify(jdbc,never()).update(contains("UPDATE betting_worker.academic_command"),any(Object[].class));}
 @Test void D03IdentityAliasIsConflict(){var c=command(AcademicCommand.CommandType.RESUME_BETS);duplicate(c,c.json());when(jdbc.queryForList(contains("FOR UPDATE"),any(Object[].class))).thenReturn(List.of(Map.of("command_id","different","canonical_payload",c.json())));assertEquals(AcademicCommandStore.Outcome.IDENTITY_CONFLICT,store.record(c,input(c)));}
 @Test void E01MalformedIsPreservedNotApplied(){var bad=new TransportMessage("source",null,"","betting_commands",new byte[]{(byte)255},"{}");assertEquals(AcademicCommandStore.Outcome.QUARANTINED,new AcademicCommandHandler(store,new AcademicCommandCodec()).receive(bad));verify(jdbc,never()).update(contains("academic_command("),any(Object[].class));verify(manager).commit(any());}
 @Test void E02BrokerIdentityMismatchIsQuarantined(){var c=command(AcademicCommand.CommandType.RESUME_BETS);var bad=new TransportMessage("source","wrong","","betting_commands",input(c).body(),"{}");assertEquals(AcademicCommandStore.Outcome.QUARANTINED,new AcademicCommandHandler(store,new AcademicCommandCodec()).receive(bad));verify(jdbc,never()).update(contains("academic_command("),any(Object[].class));}
 @Test void E03DuplicateWithMissingDurableIdentityFailsClosed(){var c=command(AcademicCommand.CommandType.SUSPEND_BETS);when(jdbc.update(contains("academic_command("),any(Object[].class))).thenReturn(0);assertThrows(IllegalStateException.class,()->store.record(c,input(c)));verify(manager).rollback(any());}
 @Test void E04LateTimestampIsNotUsedAsAuthority(){var c=command(AcademicCommand.CommandType.RESUME_BETS);store.record(c,input(c));verify(jdbc).update(contains("'NO_AUTHORITATIVE_SEQUENCE'"),any(Object[].class));verify(jdbc,never()).queryForList(contains("ORDER BY command_timestamp"),any(Object[].class));}
 @Test void R01FreshAdapterReadsPersistedResultWithoutMemory(){when(jdbc.queryForList(contains("SELECT * FROM betting_worker.academic_command"),eq("cmd"))).thenReturn(List.of(Map.of("command_id","cmd","match_id","match","source_event_id","goal","command_type","RESUME_BETS","simulated_status","SIMULATED_RESUMED","ordering_status","NO_AUTHORITATIVE_SEQUENCE","delivery_attempts",2L)));var restarted=new JdbcAcademicCommandStore(jdbc,new TransactionTemplate(manager));assertEquals(2,restarted.find("cmd").orElseThrow().deliveryAttempts());}
}
